export type Card = {
  monster: string;
  rank?: number;
};

const SPHINX = "sphinx";

/** "Sphinx — 1 point. 2 per type beyond three, else 1." */
const BASE_POINTS = 1;
const TYPE_THRESHOLD = 3;

export function scoreArmy(army: Card[]): number {
  if (!army.some((card) => card.monster === SPHINX)) return 0;

  const otherTypes = new Set(
    army.filter((card) => card.monster !== SPHINX).map((card) => card.monster),
  );
  const typesBeyondThree = Math.max(0, otherTypes.size - TYPE_THRESHOLD);
  return BASE_POINTS + (typesBeyondThree > 0 ? 2 * typesBeyondThree : 1);
}

